-- ======================================================================
-- CRA SCHEMA: Service Desk + Cyber Resilience Act compliance
-- 10 years of realistic data: 2016-01-01 to 2026-04-06
-- Respects customer onboarding, agent hire dates, product lifecycles,
-- CVE year numbering, CRA reporting windows (from Dec 11 2024), and
-- growth curves. PostgreSQL syntax.
-- ======================================================================

DROP SCHEMA IF EXISTS cra CASCADE;
CREATE SCHEMA cra;
SET search_path TO cra;

CREATE TABLE cra.categories (
    category_id  SERIAL PRIMARY KEY,
    name         VARCHAR(60) NOT NULL,
    parent_group VARCHAR(40) NOT NULL
);
CREATE TABLE cra.customers (
    customer_id  SERIAL PRIMARY KEY,
    company      VARCHAR(120) NOT NULL,
    contact_name VARCHAR(80),
    email        VARCHAR(150),
    country      VARCHAR(50),
    tier         VARCHAR(20) CHECK (tier IN ('Bronze','Silver','Gold','Platinum')),
    created_at   DATE
);
CREATE TABLE cra.agents (
    agent_id  SERIAL PRIMARY KEY,
    full_name VARCHAR(80) NOT NULL,
    team      VARCHAR(40),
    level     VARCHAR(10) CHECK (level IN ('L1','L2','L3')),
    location  VARCHAR(40),
    hired_at  DATE
);
CREATE TABLE cra.sla_policies (
    sla_id           SERIAL PRIMARY KEY,
    priority         VARCHAR(15) CHECK (priority IN ('Low','Medium','High','Critical')),
    response_mins    INT,
    resolution_hours INT
);
CREATE TABLE cra.tickets (
    ticket_id      SERIAL PRIMARY KEY,
    customer_id    INT REFERENCES cra.customers(customer_id),
    agent_id       INT REFERENCES cra.agents(agent_id),
    category_id    INT REFERENCES cra.categories(category_id),
    priority       VARCHAR(15) CHECK (priority IN ('Low','Medium','High','Critical')),
    status         VARCHAR(20) CHECK (status IN ('Open','In Progress','Pending','Resolved','Closed','Escalated')),
    channel        VARCHAR(20) CHECK (channel IN ('Email','Phone','Portal','Chat','API')),
    subject        VARCHAR(200),
    created_at     TIMESTAMP,
    first_response TIMESTAMP,
    resolved_at    TIMESTAMP,
    sla_breached   BOOLEAN DEFAULT FALSE,
    reopened_count INT DEFAULT 0
);
CREATE TABLE cra.csat_surveys (
    survey_id    SERIAL PRIMARY KEY,
    ticket_id    INT REFERENCES cra.tickets(ticket_id),
    rating       INT CHECK (rating BETWEEN 1 AND 5),
    comment      VARCHAR(300),
    submitted_at TIMESTAMP
);
CREATE TABLE cra.products (
    product_id  SERIAL PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    category    VARCHAR(50),
    cra_class   VARCHAR(20) CHECK (cra_class IN ('Default','Important-I','Important-II','Critical')),
    vendor      VARCHAR(80),
    released_at DATE,
    eol_date    DATE
);
CREATE TABLE cra.cra_requirements (
    requirement_id SERIAL PRIMARY KEY,
    code           VARCHAR(20) NOT NULL,
    title          VARCHAR(150),
    domain         VARCHAR(40),
    mandatory      BOOLEAN
);
CREATE TABLE cra.cra_compliance_checks (
    check_id       SERIAL PRIMARY KEY,
    product_id     INT REFERENCES cra.products(product_id),
    requirement_id INT REFERENCES cra.cra_requirements(requirement_id),
    status         VARCHAR(20) CHECK (status IN ('Compliant','Partial','Non-Compliant','Not-Applicable')),
    brag_status    VARCHAR(10) CHECK (brag_status IN ('Blue','Red','Amber','Green')),
    assessed_at    DATE,
    assessor       VARCHAR(80),
    risk_score     INT CHECK (risk_score BETWEEN 0 AND 100)
);
CREATE TABLE cra.cra_vulnerabilities (
    vuln_id       SERIAL PRIMARY KEY,
    product_id    INT REFERENCES cra.products(product_id),
    cve_id        VARCHAR(25),
    cvss_score    NUMERIC(3,1),
    severity      VARCHAR(15) CHECK (severity IN ('Low','Medium','High','Critical')),
    discovered_at DATE,
    disclosed_at  DATE,
    patched_at    DATE,
    status        VARCHAR(20) CHECK (status IN ('Open','Triaged','Patched','Mitigated','Accepted')),
    exploit_known BOOLEAN
);
CREATE TABLE cra.cra_incidents (
    incident_id       SERIAL PRIMARY KEY,
    product_id        INT REFERENCES cra.products(product_id),
    vuln_id           INT REFERENCES cra.cra_vulnerabilities(vuln_id),
    title             VARCHAR(200),
    severity          VARCHAR(15),
    detected_at       TIMESTAMP,
    reported_enisa_at TIMESTAMP,
    final_report_at   TIMESTAMP,
    impact_users      INT,
    status            VARCHAR(20) CHECK (status IN ('Detected','Reported','Contained','Resolved','Post-Mortem')),
    root_cause        VARCHAR(80)
);
CREATE TABLE cra.brag_snapshots (
    snapshot_id   SERIAL PRIMARY KEY,
    product_id    INT REFERENCES cra.products(product_id),
    snapshot_date DATE,
    risk_score    NUMERIC(4,1),
    brag_status   VARCHAR(10) CHECK (brag_status IN ('Blue','Red','Amber','Green'))
);

