-- ============ CSAT SURVEYS (auto-derived) ============
SELECT ticket_id,
       CASE
         WHEN sla_breached AND reopened_count > 0 THEN 1
         WHEN sla_breached THEN 2
         WHEN reopened_count > 1 THEN 2
         WHEN reopened_count = 1 THEN 3
         WHEN priority = 'Critical' THEN 5
         ELSE 4 + (ticket_id % 2)
       END,
       CASE (ticket_id % 8)
         WHEN 0 THEN 'Quick and professional'
         WHEN 1 THEN 'Took longer than expected'
         WHEN 2 THEN 'Agent was very helpful'
         WHEN 3 THEN 'Issue reopened multiple times'
         WHEN 4 THEN 'Resolved on first contact'
         WHEN 5 THEN 'Great communication throughout'
         WHEN 6 THEN 'Workaround provided quickly'
         ELSE 'Could have been faster but thorough'
       END,
       resolved_at + INTERVAL '1 day'
FROM cra.tickets
WHERE resolved_at IS NOT NULL;

