-- ======================================================================
-- VIEWS FOR VISUALIZATIONS
-- ======================================================================
CREATE OR REPLACE VIEW cra.v_ticket_volume_monthly AS
SELECT DATE_TRUNC('month', created_at) AS month, priority,
       COUNT(*) AS ticket_count,
       SUM(CASE WHEN sla_breached THEN 1 ELSE 0 END) AS breaches
FROM cra.tickets GROUP BY 1,2 ORDER BY 1,2;

CREATE OR REPLACE VIEW cra.v_ticket_volume_yearly AS
SELECT EXTRACT(YEAR FROM created_at)::int AS year, priority, COUNT(*) AS tickets
FROM cra.tickets GROUP BY 1,2 ORDER BY 1,2;

CREATE OR REPLACE VIEW cra.v_ticket_daily_heat AS
SELECT EXTRACT(DOW FROM created_at)::int AS day_of_week,
       EXTRACT(HOUR FROM created_at)::int AS hour, COUNT(*) AS tickets
FROM cra.tickets GROUP BY 1,2;

CREATE OR REPLACE VIEW cra.v_mttr_by_category AS
SELECT c.name AS category,
       ROUND(AVG(EXTRACT(EPOCH FROM (t.resolved_at - t.created_at))/3600)::numeric,2) AS avg_hours,
       COUNT(*) AS tickets
FROM cra.tickets t JOIN cra.categories c ON c.category_id = t.category_id
WHERE t.resolved_at IS NOT NULL GROUP BY c.name ORDER BY avg_hours DESC;

CREATE OR REPLACE VIEW cra.v_agent_performance AS
SELECT a.full_name, a.team, a.level,
       COUNT(t.ticket_id) AS total_tickets,
       SUM(CASE WHEN t.sla_breached THEN 1 ELSE 0 END) AS breaches,
       ROUND(AVG(s.rating)::numeric,2) AS avg_csat
FROM cra.agents a
LEFT JOIN cra.tickets t ON t.agent_id = a.agent_id
LEFT JOIN cra.csat_surveys s ON s.ticket_id = t.ticket_id
GROUP BY a.full_name, a.team, a.level ORDER BY total_tickets DESC;

CREATE OR REPLACE VIEW cra.v_channel_mix_yearly AS
SELECT EXTRACT(YEAR FROM created_at)::int AS year, channel, COUNT(*) AS tickets
FROM cra.tickets GROUP BY 1,2 ORDER BY 1,2;

CREATE OR REPLACE VIEW cra.v_customer_growth AS
SELECT DATE_TRUNC('month', created_at) AS month,
       COUNT(*) AS new_customers,
       SUM(COUNT(*)) OVER (ORDER BY DATE_TRUNC('month', created_at)) AS cumulative
FROM cra.customers GROUP BY 1 ORDER BY 1;

CREATE OR REPLACE VIEW cra.v_cra_posture AS
SELECT p.name AS product, p.cra_class,
       SUM(CASE WHEN cc.status='Compliant' THEN 1 ELSE 0 END) AS compliant,
       SUM(CASE WHEN cc.status='Partial' THEN 1 ELSE 0 END) AS partial,
       SUM(CASE WHEN cc.status='Non-Compliant' THEN 1 ELSE 0 END) AS non_compliant,
       ROUND(AVG(cc.risk_score)::numeric,1) AS avg_risk
FROM cra.products p
JOIN cra.cra_compliance_checks cc ON cc.product_id = p.product_id
GROUP BY p.name, p.cra_class ORDER BY avg_risk DESC;

-- Current BRAG distribution (latest assessment per product/requirement)
CREATE OR REPLACE VIEW cra.v_brag_distribution AS
WITH latest AS (
  SELECT DISTINCT ON (product_id, requirement_id)
         product_id, requirement_id, brag_status
  FROM cra.cra_compliance_checks
  ORDER BY product_id, requirement_id, assessed_at DESC
)
SELECT brag_status, COUNT(*) AS total,
       ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),1) AS pct
FROM latest GROUP BY brag_status ORDER BY brag_status;

CREATE OR REPLACE VIEW cra.v_brag_by_class AS
WITH latest AS (
  SELECT DISTINCT ON (product_id, requirement_id)
         product_id, requirement_id, brag_status
  FROM cra.cra_compliance_checks
  ORDER BY product_id, requirement_id, assessed_at DESC
)
SELECT p.cra_class, l.brag_status, COUNT(*) AS total
FROM latest l JOIN cra.products p ON p.product_id = l.product_id
GROUP BY p.cra_class, l.brag_status ORDER BY p.cra_class, l.brag_status;

-- BRAG trend over time from weekly snapshots
CREATE OR REPLACE VIEW cra.v_brag_trend AS
SELECT snapshot_date, brag_status, COUNT(*) AS products,
       ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (PARTITION BY snapshot_date),1) AS pct
FROM cra.brag_snapshots GROUP BY snapshot_date, brag_status ORDER BY snapshot_date, brag_status;

CREATE OR REPLACE VIEW cra.v_brag_latest AS
SELECT DISTINCT ON (product_id) p.name, bs.snapshot_date, bs.risk_score, bs.brag_status
FROM cra.brag_snapshots bs JOIN cra.products p ON p.product_id = bs.product_id
ORDER BY product_id, snapshot_date DESC;

CREATE OR REPLACE VIEW cra.v_vuln_aging AS
SELECT p.name AS product, v.severity, v.status,
       CASE WHEN v.patched_at IS NOT NULL THEN v.patched_at - v.discovered_at
            ELSE CURRENT_DATE - v.discovered_at END AS age_days,
       v.exploit_known, EXTRACT(YEAR FROM v.discovered_at)::int AS disc_year
FROM cra.cra_vulnerabilities v JOIN cra.products p ON p.product_id = v.product_id;

CREATE OR REPLACE VIEW cra.v_vuln_yearly_trend AS
SELECT EXTRACT(YEAR FROM discovered_at)::int AS year, severity, COUNT(*) AS cves
FROM cra.cra_vulnerabilities GROUP BY 1,2 ORDER BY 1,2;

CREATE OR REPLACE VIEW cra.v_cra_incident_sla AS
SELECT i.incident_id, p.name AS product, i.severity, i.detected_at,
       EXTRACT(EPOCH FROM (i.reported_enisa_at - i.detected_at))/3600 AS hours_to_report,
       CASE WHEN i.final_report_at IS NOT NULL
            THEN EXTRACT(DAY FROM (i.final_report_at - i.detected_at)) ELSE NULL END AS days_to_final,
       CASE
         WHEN i.detected_at::date < DATE '2024-12-11' THEN 'Pre-CRA'
         WHEN EXTRACT(EPOCH FROM (i.reported_enisa_at - i.detected_at))/3600 <= 24 THEN 'Within 24h'
         ELSE 'Breach'
       END AS early_warning_sla
FROM cra.cra_incidents i JOIN cra.products p ON p.product_id = i.product_id;
